import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../core/widgets/civix_widgets.dart';
import '../../core/theme/app_theme.dart';
import '../../data/models/models.dart';
import '../../data/services/firestore_service.dart';

class AgentsScreen extends StatelessWidget{const AgentsScreen({super.key});@override Widget build(BuildContext context)=>GradientShell(child:SafeArea(child:StreamBuilder<List<CrisisReport>>(stream:context.read<FirestoreService>().crises(),builder:(c,cs){final crisis=cs.data?.isNotEmpty==true?cs.data!.first:null;if(crisis==null)return const Center(child:Text('No crisis found. Seed Firestore or submit a report.'));return StreamBuilder<List<AgentResult>>(stream:context.read<FirestoreService>().agents(crisis.id),builder:(c,s){final agents=s.data??[];return ListView(padding:const EdgeInsets.all(16),children:[Text('AI Agent Workflow',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w900)),const SizedBox(height:8),Text(crisis.title,style:const TextStyle(color:CivixColors.muted)),const SizedBox(height:16),...agents.map((a)=>Padding(padding:const EdgeInsets.only(bottom:12),child:GlassCard(child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[const Icon(Icons.hub,color:CivixColors.cyan),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(a.agentName,style:const TextStyle(fontWeight:FontWeight.w900))),StatusPill(a.status,CivixColors.green)]),const SizedBox(height:6),Text(a.summary),const SizedBox(height:8),LinearProgressIndicator(value:a.confidence/100),const SizedBox(height:6),Text('${a.confidence.toInt()}% confidence',style:const TextStyle(color:CivixColors.muted,fontSize:12))]))]))))];});}))));}
